package main

import (
	"context"
	"errors"
	"fmt"
	"time"
)

// queryDB 模拟一次可被 ctx 中断的数据库查询。
// 核心模式：select 监听 ctx.Done() 与结果 channel，谁先到用谁。
func queryDB(ctx context.Context, name string, cost time.Duration) (string, error) {
	resultCh := make(chan string, 1) // 带缓冲，避免 worker 协程永久阻塞
	go func() {
		time.Sleep(cost) // 模拟慢查询
		resultCh <- "来自" + name + "的结果"
	}()

	select {
	case <-ctx.Done():
		return "", ctx.Err() // Canceled 或 DeadlineExceeded
	case res := <-resultCh:
		return res, nil
	}
}

func main() {
	// 1) 超时控制：整个操作最多 200ms
	ctx, cancel := context.WithTimeout(context.Background(), 200*time.Millisecond)
	defer cancel() // 必须调用，否则 ctx 无法被 GC，造成泄漏

	start := time.Now()
	res, err := queryDB(ctx, "user_table", 500*time.Millisecond)
	if errors.Is(err, context.DeadlineExceeded) {
		fmt.Println("查询超时:", err)
	} else if err != nil {
		fmt.Println("查询失败:", err)
	} else {
		fmt.Println("查询成功:", res)
	}
	fmt.Println("实际耗时:", time.Since(start).Round(time.Millisecond))

	// 2) 手动取消：父 ctx 取消，子 ctx 自动跟随取消
	parent, cancelParent := context.WithCancel(context.Background())
	child, cancelChild := context.WithCancel(parent)
	defer cancelChild()

	go func() {
		time.Sleep(50 * time.Millisecond)
		cancelParent() // 关闭父 ctx
	}()

	select {
	case <-child.Done():
		fmt.Println("子 ctx 被取消:", child.Err()) // context canceled
	case <-time.After(200 * time.Millisecond):
		fmt.Println("子 ctx 未被取消")
	}
}

